/* Add the shard reply of a single shard based off the given primary node. */
void addShardReplyForClusterShards(client *c, list *nodes) {
    serverAssert(listLength(nodes) > 0);
    clusterNode *n = listNodeValue(listFirst(nodes));
    addReplyMapLen(c, 2);
    addReplyBulkCString(c, "slots");

    /* Use slot_info_pairs from the primary only */
    n = clusterNodeGetPrimary(n);

    if (n->slot_info_pairs != NULL) {
        serverAssert((n->slot_info_pairs_count % 2) == 0);
        addReplyArrayLen(c, n->slot_info_pairs_count);
        for (int i = 0; i < n->slot_info_pairs_count; i++) {
            addReplyLongLong(c, (unsigned long)n->slot_info_pairs[i]);
        }
    } else {
        /* If no slot info pair is provided, the node owns no slots */
        addReplyArrayLen(c, 0);
    }

    addReplyBulkCString(c, "nodes");
    addReplyArrayLen(c, listLength(nodes));
    listNode *ln = listFirst(nodes);
    while (ln != NULL) {
        clusterNode *node = listNodeValue(ln);
        int reply_count = 0;
        void *node_replylen = addReplyDeferredLen(c);
        addReplyBulkCString(c, "id");
        addReplyBulkCBuffer(c, node->name, CLUSTER_NAMELEN);
        reply_count++;

        if (node->tcp_port) {
            addReplyBulkCString(c, "port");
            addReplyLongLong(c, node->tcp_port);
            reply_count++;
        }

        if (node->tls_port) {
            addReplyBulkCString(c, "tls-port");
            addReplyLongLong(c, node->tls_port);
            reply_count++;
        }

        addReplyBulkCString(c, "ip");
        addReplyBulkCString(c, clusterNodeIp(node, c));
        reply_count++;

        addReplyBulkCString(c, "endpoint");
        addReplyBulkCString(c, clusterNodePreferredEndpoint(node, c));
        reply_count++;

        if (sdslen(node->hostname) != 0) {
            addReplyBulkCString(c, "hostname");
            addReplyBulkCBuffer(c, node->hostname, sdslen(node->hostname));
            reply_count++;
        }

        long long node_offset;
        if (!(node->flags & CLUSTER_NODE_MYSELF)) {
            node_offset = node->repl_offset;
        } else if (!nodeIsReplica(node)) {
            node_offset = server.primary_repl_offset;
        } else {
            node_offset = 0;
            if (server.primary_host != NULL) {
                if (server.primary) {
                    node_offset = server.primary->reploff;
                } else if (server.cached_primary) {
                    node_offset = server.cached_primary->reploff;
                }
            }
            if (node_offset < 0) {
                node_offset = 0;
            }
        }

        addReplyBulkCString(c, "role");
        addReplyBulkCString(c, nodeIsReplica(node) ? "replica" : "master");
        reply_count++;

        addReplyBulkCString(c, "replication-offset");
        addReplyLongLong(c, node_offset);
        reply_count++;

        addReplyBulkCString(c, "health");
        const char *health_msg = NULL;
        if (nodeFailed(node)) {
            health_msg = "fail";
        } else if (nodeIsReplica(node) && node_offset == 0) {
            health_msg = "loading";
        } else {
            health_msg = "online";
        }
        addReplyBulkCString(c, health_msg);
        reply_count++;

        setDeferredMapLen(c, node_replylen, reply_count);
        zfree(node->slot_info_pairs);
        node->slot_info_pairs = NULL;
        node->slot_info_pairs_count = 0;
        ln = listNextNode(ln);
    }
}

/* Add to the output buffer of the given client, an array of slot (start, end)
